# Shared by build/07 and build/13 (sourced, needs build/00-env.sh): the CLI's generated BuildInfo.scala.
# write_buildinfo <file>
write_buildinfo() {
  local NATIVE_BINARY_VERSION
  # scala-native artifacts are named with major.minor only (e.g. nativelib_native0.5_3).
  NATIVE_BINARY_VERSION="$(echo "$SCALA_NATIVE_VERSION" | cut -d. -f1,2)"
cat > "$1" <<EOF
object BuildInfo:
  val scalinoVersion: String = "$SCALINO_VERSION"
  val scalaVersion: String = "$SCALA_VERSION"
  val nativeBinaryVersion: String = "$NATIVE_BINARY_VERSION"
  val nativeVersion: String = "$SCALA_NATIVE_VERSION"
  val scalaJsVersion: String = "$SCALAJS_VERSION"
  /** Upstream versions and checksums of what \`scalino sysroot build\` downloads (versions.env). */
  val sysrootPins: Map[String, String] = Map(
$(for v in DEBIAN_SNAPSHOT MUSL_DEB_VERSION MUSL_DEV_AMD64_SHA256 MUSL_DEV_ARM64_SHA256 ZIG_VERSION ZIG_SHA256 LLVM_MINGW_VERSION LLVM_MINGW_SHA256 LLVM_MINGW_LINUX_AARCH64_SHA256 LLVM_MINGW_MACOS_UNIVERSAL_SHA256 LLVM_MINGW_WINDOWS_X86_64_SHA256 LLVM_MINGW_WINDOWS_AARCH64_SHA256 MINGW_W64_LICENSE_TAG MINGW_W64_RUNTIME_LICENSE_SHA256 MINGW_W64_LICENSE_SHA256 GLIBC_DEB_VERSION LINUX_LIBC_DEV_VERSION LIBCLANG_RT_DEB_VERSION GLIBC_LIBC6_AMD64_SHA256 GLIBC_LIBC6_DEV_AMD64_SHA256 LINUX_LIBC_DEV_AMD64_SHA256 GLIBC_LIBC6_ARM64_SHA256 GLIBC_LIBC6_DEV_ARM64_SHA256 LINUX_LIBC_DEV_ARM64_SHA256 LIBCLANG_RT_AMD64_SHA256 LIBCLANG_RT_ARM64_SHA256 ZLIB_ALPINE_VERSION ZLIB_ALPINE_DEV_X86_64_SHA256 ZLIB_ALPINE_STATIC_X86_64_SHA256 ZLIB_ALPINE_DEV_AARCH64_SHA256 ZLIB_ALPINE_STATIC_AARCH64_SHA256 ZLIB_DEBIAN_VERSION ZLIB_DEBIAN_AMD64_SHA256 ZLIB_DEBIAN_ARM64_SHA256 OPENSSL_ALPINE_BRANCH OPENSSL_ALPINE_VERSION OPENSSL_ALPINE_LICENSE_VERSION OPENSSL_ALPINE_LICENSE_SHA256 OPENSSL_ALPINE_STATIC_X86_64_SHA256 OPENSSL_ALPINE_DEV_X86_64_SHA256 OPENSSL_ALPINE_STATIC_AARCH64_SHA256 OPENSSL_ALPINE_DEV_AARCH64_SHA256 OPENSSL_DEBIAN_VERSION OPENSSL_DEBIAN_AMD64_SHA256 OPENSSL_DEBIAN_ARM64_SHA256 OPENSSL_MSYS2_VERSION OPENSSL_MSYS2_X86_64_SHA256 OPENSSL_MSYS2_AARCH64_SHA256 OPENSSL_BREW_VERSION OPENSSL_BREW_X86_64_SHA256 OPENSSL_BREW_ARM64_SHA256 IDN2_ALPINE_VERSION IDN2_ALPINE_STATIC_X86_64_SHA256 IDN2_ALPINE_DEV_X86_64_SHA256 IDN2_ALPINE_STATIC_AARCH64_SHA256 IDN2_ALPINE_DEV_AARCH64_SHA256 UNISTRING_ALPINE_VERSION UNISTRING_ALPINE_STATIC_X86_64_SHA256 UNISTRING_ALPINE_STATIC_AARCH64_SHA256 IDN2_DEBIAN_VERSION IDN2_DEBIAN_AMD64_SHA256 IDN2_DEBIAN_ARM64_SHA256 UNISTRING_DEBIAN_VERSION UNISTRING_DEBIAN_AMD64_SHA256 UNISTRING_DEBIAN_ARM64_SHA256 IDN2_MSYS2_VERSION IDN2_MSYS2_X86_64_SHA256 IDN2_MSYS2_AARCH64_SHA256 UNISTRING_MSYS2_VERSION UNISTRING_MSYS2_X86_64_SHA256 UNISTRING_MSYS2_AARCH64_SHA256 ICONV_MSYS2_VERSION ICONV_MSYS2_X86_64_SHA256 ICONV_MSYS2_AARCH64_SHA256 IDN2_BREW_VERSION IDN2_BREW_X86_64_SHA256 IDN2_BREW_ARM64_SHA256 UNISTRING_BREW_VERSION UNISTRING_BREW_X86_64_SHA256 UNISTRING_BREW_ARM64_SHA256 GETTEXT_BREW_VERSION GETTEXT_BREW_X86_64_SHA256 GETTEXT_BREW_ARM64_SHA256 IDN2_LICENSE_VERSION IDN2_LICENSE_LESSER_SHA256 IDN2_LICENSE_UNICODE_SHA256 UNISTRING_LICENSE_VERSION UNISTRING_LICENSE_SHA256 S2N_VERSION S2N_SHA256 CURL_VERSION CURL_SHA256 ZLIB_VERSION ZLIB_SHA256 CURL_MSYS2_VERSION CURL_MSYS2_X86_64_SHA256 CURL_MSYS2_AARCH64_SHA256 LIBSSH2_MSYS2_VERSION LIBSSH2_MSYS2_X86_64_SHA256 LIBSSH2_MSYS2_AARCH64_SHA256 ZLIB_MSYS2_VERSION ZLIB_MSYS2_X86_64_SHA256 ZLIB_MSYS2_AARCH64_SHA256 BROTLI_MSYS2_VERSION BROTLI_MSYS2_X86_64_SHA256 BROTLI_MSYS2_AARCH64_SHA256 ZSTD_MSYS2_VERSION ZSTD_MSYS2_X86_64_SHA256 ZSTD_MSYS2_AARCH64_SHA256 NGHTTP2_MSYS2_VERSION NGHTTP2_MSYS2_X86_64_SHA256 NGHTTP2_MSYS2_AARCH64_SHA256 NGTCP2_MSYS2_VERSION NGTCP2_MSYS2_X86_64_SHA256 NGTCP2_MSYS2_AARCH64_SHA256 NGHTTP3_MSYS2_VERSION NGHTTP3_MSYS2_X86_64_SHA256 NGHTTP3_MSYS2_AARCH64_SHA256 LIBPSL_MSYS2_VERSION LIBPSL_MSYS2_X86_64_SHA256 LIBPSL_MSYS2_AARCH64_SHA256; do echo "    \"$v\" -> \"${!v}\","; done)
  )
EOF
}
